    'kjv_JHN_3': ChapterData(
      book: 'John',
      bookCode: 'JHN',
      chapter: 3,
      translationId: 'kjv',
      translationName: 'King James Version',
      verses: [
        VerseModel(verse: 1, text: "There was a man of the Pharisees, named Nicodemus, a ruler of the Jews:"),
        VerseModel(verse: 2, text: "The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him."),
        VerseModel(verse: 3, text: "Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God."),
        VerseModel(verse: 4, text: "Nicodemus saith unto him, How can a man be born when he is old? can he enter the second time into his mother’s womb, and be born?"),
        VerseModel(verse: 5, text: "Jesus answered, Verily, verily, I say unto thee, Except a man be born of water and of the Spirit, he cannot enter into the kingdom of God."),
        VerseModel(verse: 6, text: "That which is born of the flesh is flesh; and that which is born of the Spirit is spirit."),
        VerseModel(verse: 7, text: "Marvel not that I said unto thee, Ye must be born again."),
        VerseModel(verse: 8, text: "The wind bloweth where it listeth, and thou hearest the sound thereof, but canst not tell whence it cometh, and whither it goeth: so is every one that is born of the Spirit."),
        VerseModel(verse: 9, text: "Nicodemus answered and said unto him, How can these things be?"),
        VerseModel(verse: 10, text: "Jesus answered and said unto him, Art thou a master of Israel, and knowest not these things?"),
        VerseModel(verse: 11, text: "Verily, verily, I say unto thee, We speak that we do know, and testify that we have seen; and ye receive not our witness."),
        VerseModel(verse: 12, text: "If I have told you earthly things, and ye believe not, how shall ye believe, if I tell you of heavenly things?"),
        VerseModel(verse: 13, text: "And no man hath ascended up to heaven, but he that came down from heaven, even the Son of man which is in heaven."),
        VerseModel(verse: 14, text: "And as Moses lifted up the serpent in the wilderness, even so must the Son of man be lifted up:"),
        VerseModel(verse: 15, text: "That whosoever believeth in him should not perish, but have eternal life."),
        VerseModel(verse: 16, text: "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life."),
        VerseModel(verse: 17, text: "For God sent not his Son into the world to condemn the world; but that the world through him might be saved."),
        VerseModel(verse: 18, text: "He that believeth on him is not condemned: but he that believeth not is condemned already, because he hath not believed in the name of the only begotten Son of God."),
        VerseModel(verse: 19, text: "And this is the condemnation, that light is come into the world, and men loved darkness rather than light, because their deeds were evil."),
        VerseModel(verse: 20, text: "For every one that doeth evil hateth the light, neither cometh to the light, lest his deeds should be reproved."),
        VerseModel(verse: 21, text: "But he that doeth truth cometh to the light, that his deeds may be made manifest, that they are wrought in God."),
        VerseModel(verse: 22, text: "After these things came Jesus and his disciples into the land of Judea; and there he tarried with them, and baptized."),
        VerseModel(verse: 23, text: "And John also was baptizing in Ænon near to Salim, because there was much water there: and they came, and were baptized."),
        VerseModel(verse: 24, text: "For John was not yet cast into prison."),
        VerseModel(verse: 25, text: "Then there arose a question between some of John’s disciples and the Jews about purifying."),
        VerseModel(verse: 26, text: "And they came unto John, and said unto him, Rabbi, he that was with thee beyond Jordan, to whom thou barest witness, behold, the same baptizeth, and all men come to him."),
        VerseModel(verse: 27, text: "John answered and said, A man can receive nothing, except it be given him from heaven."),
        VerseModel(verse: 28, text: "Ye yourselves bear me witness, that I said, I am not the Christ, but that I am sent before him."),
        VerseModel(verse: 29, text: "He that hath the bride is the bridegroom: but the friend of the bridegroom, which standeth and heareth him, rejoiceth greatly because of the bridegroom’s voice: this my joy therefore is fulfilled."),
        VerseModel(verse: 30, text: "He must increase, but I must decrease."),
        VerseModel(verse: 31, text: "He that cometh from above is above all: he that is of the earth is earthly, and speaketh of the earth: he that cometh from heaven is above all."),
