    'kjv_1TH_5': ChapterData(
      book: '1 Thessalonians',
      bookCode: '1TH',
      chapter: 5,
      translationId: 'kjv',
      translationName: 'King James Version',
      verses: [
        VerseModel(verse: 1, text: "But of the times and the seasons, brethren, ye have no need that I write unto you."),
        VerseModel(verse: 2, text: "For yourselves know perfectly that the day of the Lord so cometh as a thief in the night."),
        VerseModel(verse: 3, text: "For when they shall say, Peace and safety; then sudden destruction cometh upon them, as travail upon a woman with child; and they shall not escape."),
        VerseModel(verse: 4, text: "But ye, brethren, are not in darkness, that that day should overtake you as a thief."),
        VerseModel(verse: 5, text: "Ye are all the children of light, and the children of the day: we are not of the night, nor of darkness."),
        VerseModel(verse: 6, text: "Therefore let us not sleep, as do others; but let us watch and be sober."),
        VerseModel(verse: 7, text: "For they that sleep sleep in the night; and they that be drunken are drunken in the night."),
        VerseModel(verse: 8, text: "But let us, who are of the day, be sober, putting on the breastplate of faith and love; and for an helmet, the hope of salvation."),
        VerseModel(verse: 9, text: "For God hath not appointed us to wrath, but to obtain salvation by our Lord Jesus Christ,"),
        VerseModel(verse: 10, text: "Who died for us, that, whether we wake or sleep, we should live together with him."),
        VerseModel(verse: 11, text: "Wherefore comfort yourselves together, and edify one another, even as also ye do."),
        VerseModel(verse: 12, text: "And we beseech you, brethren, to know them which labour among you, and are over you in the Lord, and admonish you;"),
        VerseModel(verse: 13, text: "And to esteem them very highly in love for their work’s sake. And be at peace among yourselves."),
        VerseModel(verse: 14, text: "Now we exhort you, brethren, warn them that are unruly, comfort the feebleminded, support the weak, be patient toward all men."),
        VerseModel(verse: 15, text: "See that none render evil for evil unto any man; but ever follow that which is good, both among yourselves, and to all men."),
        VerseModel(verse: 16, text: "Rejoice evermore."),
        VerseModel(verse: 17, text: "Pray without ceasing."),
        VerseModel(verse: 18, text: "In every thing give thanks: for this is the will of God in Christ Jesus concerning you."),
        VerseModel(verse: 19, text: "Quench not the Spirit."),
        VerseModel(verse: 20, text: "Despise not prophesyings."),
        VerseModel(verse: 21, text: "Prove all things; hold fast that which is good."),
        VerseModel(verse: 22, text: "Abstain from all appearance of evil."),
        VerseModel(verse: 23, text: "And the very God of peace sanctify you wholly; and I pray God your whole spirit and soul and body be preserved blameless unto the coming of our Lord Jesus Christ."),
        VerseModel(verse: 24, text: "Faithful is he that calleth you, who also will do it."),
        VerseModel(verse: 25, text: "Brethren, pray for us."),
        VerseModel(verse: 26, text: "Greet all the brethren with an holy kiss."),
        VerseModel(verse: 27, text: "I charge you by the Lord that this epistle be read unto all the holy brethren."),
        VerseModel(verse: 28, text: "The grace of our Lord Jesus Christ be with you. Amen. The first epistle unto the Thessalonians was written from Athens."),
      ],
    ),
